--- blog page ---
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { Panel, PanelHeader, PanelTitle, PanelTitleSup } from "@/components/panel";
import { PostSearch } from "@/components/post-search";
import { getPublishedPosts } from "@/lib/blog";
import { serializeJsonLd } from "@/lib/json-ld";
import { site } from "@/lib/site";

/**
 * With nothing published the route 404s, so it must not advertise itself as a
 * Blog — naming a page the Visitor cannot reach is a lie told by the tab.
 */
export function generateMetadata(): Metadata {
  if (getPublishedPosts().length === 0) return { title: "Nothing lives here" };
  return {
    title: "Blog",
    alternates: { canonical: `${site.url}/blog` },
  };
}

type BlogPageProps = {
  searchParams?: Promise<{ q?: string | string[] }>;
};

export default async function BlogPage({ searchParams }: BlogPageProps) {
  // Nothing empty is ever shown to a Visitor (CONTEXT.md → Blog / Post).
  const posts = getPublishedPosts();
  if (posts.length === 0) notFound();

  const params = await searchParams;
  const initialQuery = Array.isArray(params?.q)
    ? (params.q[0] ?? "")
    : (params?.q ?? "");

  // The body is the one thing a row never draws, and the rows are drawn in the
  // browser here — so it is dropped before the list crosses over rather than
  // shipped down and ignored.
  const summaries = posts.map(({ content: _content, ...summary }) => summary);

  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "Blog",
    "@id": `${site.url}/blog`,
    name: "Blog",
    url: `${site.url}/blog`,
    author: { "@type": "Person", name: site.name, url: site.url },
    blogPost: posts.map((post) => ({
      "@type": "BlogPosting",
      "@id": `${site.url}/blog/${post.slug}`,
      headline: post.title,
      description: post.summary,
      url: `${site.url}/blog/${post.slug}`,
      datePublished: post.publishedAt,
    })),
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: serializeJsonLd(jsonLd) }}
      />

      {/* One panel, not a heading floating above a list: the index is a single
          thing on the page, and the site draws single things inside rails.
          There is no tagline under the title — the reference needs one because
          its heading *is* the tagline; ours says the word the nav promised and
          then gets out of the way of the posts. */}
      <Panel id="blog">
        <PanelHeader>
          <PanelTitle as="h1">
            Blog
            <PanelTitleSup className="tabular-nums">
              {posts.length}
            </PanelTitleSup>
          </PanelTitle>
        </PanelHeader>

        <PostSearch posts={summaries} initialQuery={initialQuery} />
      </Panel>
    </>
  );
}

--- slug ---
import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { ArrowLeft } from "@/components/icons";
import { CustomMDX } from "@/components/mdx";
import {
  Panel,
  PanelContent,
  PanelDescription,
  PanelHeader,
  PanelTitle,
} from "@/components/panel";
import { PostActions } from "@/components/post-actions";
import { PostNeighbours } from "@/components/post-neighbours";
import { TocInline } from "@/components/toc-inline";
import { getPostBySlug, getPublishedPosts } from "@/lib/blog";
import { findNeighbours, formatPostDate, postMarkdown } from "@/lib/posts";
import { ogImagePath } from "@/lib/discovery";
import { serializeJsonLd } from "@/lib/json-ld";
import { site } from "@/lib/site";
import { tableOfContents } from "@/lib/toc";

type PageProps = { params: Promise<{ slug: string }> };

export function generateStaticParams() {
  return getPublishedPosts().map((post) => ({ slug: post.slug }));
}

export async function generateMetadata({
  params,
}: PageProps): Promise<Metadata> {
  const { slug } = await params;
  const post = getPostBySlug(slug);
  if (!post) return {};

  const image = post.image ?? ogImagePath(post.title);
  const url = `${site.url}/blog/${post.slug}`;

  return {
    title: post.title,
    description: post.summary,
    alternates: { canonical: url },
    openGraph: {
      type: "article",
      title: post.title,
      description: post.summary,
      url,
      publishedTime: post.publishedAt,
      images: [{ url: image }],
    },
    twitter: {
      card: "summary_large_image",
      title: post.title,
      description: post.summary,
      images: [image],
    },
  };
}

export default async function PostPage({ params }: PageProps) {
  const { slug } = await params;
  const post = getPostBySlug(slug);
  if (!post) notFound();

  const url = `${site.url}/blog/${post.slug}`;

  // The index is newest-first, so the neighbours come from the same order the
  // Visitor saw on the way in.
  const { newer, older } = findNeighbours(getPublishedPosts(), post.slug);
  const neighbour = (post: { slug: string; title: string } | null) =>
    post ? { slug: post.slug, title: post.title } : null;

  const jsonLd = [
    {
      "@context": "https://schema.org",
      "@type": "BlogPosting",
      headline: post.title,
      description: post.summary,
      datePublished: post.publishedAt,
      dateModified: post.publishedAt,
      url,
      image: `${site.url}${post.image ?? ogImagePath(post.title)}`,
      author: { "@type": "Person", name: site.name, url: site.url },
      isPartOf: { "@type": "Blog", "@id": `${site.url}/blog` },
    },
    {
      "@context": "https://schema.org",
      "@type": "BreadcrumbList",
      itemListElement: [
        { "@type": "ListItem", position: 1, name: "Home", item: site.url },
        {
          "@type": "ListItem",
          position: 2,
          name: "Blog",
          item: `${site.url}/blog`,
        },
        { "@type": "ListItem", position: 3, name: post.title, item: url },
      ],
    },
  ];

  return (
    <article className="[--separator-height:--spacing(8)]">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: serializeJsonLd(jsonLd) }}
      />

      {/* The toolbar: the way back on the left, what you can do with the post
          on the right. Above the title because it is about the document rather
          than in it — a share button under a thousand words is a share button
          you decided to press in the first paragraph and then had to hunt
          for. */}
      <div className="screen-line-bottom flex items-center justify-between gap-2 border-x border-line py-2 pr-2 pl-4">
        <Link
          href="/blog"
          className="link-underline extend-touch-target inline-flex items-center gap-1.5 text-sm text-muted-foreground transition-colors hover:text-foreground"
        >
          <ArrowLeft className="size-3.5" />
          Blog
        </Link>

        <PostActions
          markdown={postMarkdown(post, url, post.content)}
          rawUrl={`${url}/raw.md`}
          url={url}
          title={post.title}
          newer={neighbour(newer)}
          older={neighbour(older)}
        />
      </div>

      <Panel>
        <PanelHeader>
          <PanelTitle as="h1">{post.title}</PanelTitle>
          <PanelDescription>
            <p className="text-balance">{post.summary}</p>
            <p className="typeset-timescale mt-2 flex flex-wrap items-center gap-x-2 font-mono tabular-nums">
              <time dateTime={post.publishedAt}>
                {formatPostDate(post.publishedAt)}
              </time>
              <span aria-hidden>·</span>
              <span>{post.readingTimeMinutes} min read</span>
            </p>
          </PanelDescription>
        </PanelHeader>

        <TocInline entries={tableOfContents(post.content)} />

        <PanelContent className="typeset prose">
          <CustomMDX source={post.content} />
        </PanelContent>
      </Panel>

      <PostNeighbours newer={neighbour(newer)} older={neighbour(older)} />
    </article>
  );
}

--- sitemap/feed/robots ---
import type { MetadataRoute } from "next";
import { buildSitemapEntries } from "@/lib/discovery";
import { site } from "@/lib/site";
import { getPublishedPosts } from "@/lib/blog";

export default function sitemap(): MetadataRoute.Sitemap {
  return buildSitemapEntries({
    siteUrl: site.url,
    posts: getPublishedPosts(),
  });
}
import { site } from "@/lib/site";
import { buildRssXml } from "@/lib/discovery";
import { getPublishedPosts } from "@/lib/blog";

export async function GET() {
  const xml = buildRssXml({
    siteUrl: site.url,
    siteName: site.name,
    description: site.description,
    posts: getPublishedPosts(),
    feedPath: site.rssPath,
  });

  return new Response(xml, {
    headers: {
      "Content-Type": "application/rss+xml; charset=utf-8",
      "Cache-Control": "s-maxage=600, stale-while-revalidate",
    },
  });
}
import type { MetadataRoute } from "next";
import { site } from "@/lib/site";

export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      {
        userAgent: "*",
        allow: "/",
      },
    ],
    sitemap: `${site.url}/sitemap.xml`,
    host: site.url,
  };
}

--- release ADR ---
# Preview-first release lane

Status: accepted

## Context

The Vercel project currently treats `main` as Production. That makes a merge immediately visible on `dhruv2mars.com`, before owner review. PR previews already exist, but they are ephemeral URLs and do not provide one stable review address for the next release.

## Decision

Use Vercel's branch-tracked Preview domain for release review:

- `main` becomes a Preview branch.
- `preview.dhruv2mars.com` tracks the latest Preview Deployment from `main`.
- `release` becomes the Vercel Production Branch and stays protected.
- Owner approval promotes the exact reviewed Preview Deployment to Production.

Keep the canonical Vercel project `dhruv2mars`. Do not create a second project for staging.

## Consequences

Merges to `main` are safe to review at a stable URL. GA becomes an explicit promotion step, so production can remain on the last approved deployment. Preview and Production environment variables remain separate.

--- release process ---
# Release process

Portfolio ships preview-first.

- `main` is the review branch. Every push creates a Preview Deployment.
- `preview.dhruv2mars.com` follows the latest `main` Preview Deployment.
- `release` is the Vercel Production Branch. Keep it protected and do not push to it during normal work.
- `dhruv2mars.com` is GA. It changes only when a confirmed Preview Deployment is promoted.

## One-time Vercel setup

1. Create a `release` branch from the current GA commit if it does not exist.
2. Open [Vercel project settings](https://vercel.com/dhruv2mars/dhruv2mars/settings/environments). Go to Environments → Production → Branch Tracking. Set the Production Branch to `release`.
3. Open [Vercel domain settings](https://vercel.com/dhruv2mars/dhruv2mars/settings/domains). Add `preview.dhruv2mars.com`, then edit it and connect it to the Preview environment with Git Branch `main`.
4. At the DNS provider for `dhruv2mars.com`, add the exact record Vercel shows for `preview`. Current Vercel inspection requests `A preview.dhruv2mars.com 76.76.21.21`; use the project value if it changes.
5. Leave `dhruv2mars.com` and `www.dhruv2mars.com` connected to Production.

The branch setting matters. Vercel rejects a Preview domain that tracks the current Production Branch, so `main` must stop being Production before the custom Preview domain can track it.

## Each release

1. Open a PR. Use its unique Vercel Preview URL for change review.
2. Merge the approved PR into `main`. Vercel deploys `main` as Preview and updates `https://preview.dhruv2mars.com`.
3. Check the stable Preview URL, then promote that exact deployment only after sign-off:

   ```bash
   vercel promote <deployment-url>
   ```

   The same action is available from the deployment menu in Vercel as **Promote to Production**.

4. Confirm GA at `https://dhruv2mars.com`. Do not use `vercel --prod` for an unconfirmed build.

## Checks

```bash
dig +short preview.dhruv2mars.com
curl -I https://preview.dhruv2mars.com
curl -I https://dhruv2mars.com
```

The first command should resolve to Vercel. Both HTTP requests should return `200` or the site's expected redirect response.

