import type { PostRecord } from "./blog";

export type RssInput = {
  siteUrl: string;
  siteName: string;
  description: string;
  posts: readonly PostRecord[];
  /** The feed's own address, so it can point at itself. */
  feedPath: string;
  /** Injected so the output is a pure function of its input, and testable. */
  now?: Date;
};

export type SitemapEntry = {
  url: string;
  lastModified: string;
};

function escapeXml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

/**
 * RSS 2.0, with the three declarations readers actually use and that a
 * hand-rolled feed usually forgets.
 *
 * `atom:link rel="self"` is the feed's own address: a reader that has been
 * handed the file by any other route — a proxy, a mirror, a copy-paste —
 * learns where to poll from here. `lastBuildDate` is what lets a reader ask
 * "has anything changed?" without downloading the whole feed. `language` is
 * what tells it not to run the titles through a translator.
 *
 * The feed carries summaries, not whole articles. That is a choice: the posts
 * are MDX with components in them, and a feed that ships half-rendered markup
 * is worse than one that ships a paragraph and a link.
 */
export function buildRssXml({
  siteUrl,
  siteName,
  description,
  posts,
  feedPath,
  now = new Date(),
}: RssInput): string {
  const ordered = posts
    .slice()
    .sort(
      (a, b) =>
        new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime(),
    );

  const items = ordered
    .map((post) => {
      const url = `${siteUrl}/blog/${encodeURIComponent(post.slug)}`;
      return `    <item>
      <title>${escapeXml(post.title)}</title>
      <link>${escapeXml(url)}</link>
      <guid isPermaLink="true">${escapeXml(url)}</guid>
      <description>${escapeXml(post.summary)}</description>
      <pubDate>${new Date(post.publishedAt).toUTCString()}</pubDate>
    </item>`;
    })
    .join("\n");

  // The newest post if there is one, otherwise the moment the feed was built:
  // a `lastBuildDate` that moves on every request would make every poll look
  // like news.
  const lastBuild = ordered[0]
    ? new Date(ordered[0].publishedAt)
    : now;

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(siteName)}</title>
    <link>${escapeXml(siteUrl)}</link>
    <description>${escapeXml(description)}</description>
    <language>en</language>
    <lastBuildDate>${lastBuild.toUTCString()}</lastBuildDate>
    <atom:link href="${escapeXml(`${siteUrl}${feedPath}`)}" rel="self" type="application/rss+xml" />
${items ? `${items}\n` : ""}  </channel>
</rss>`;
}

export function buildSitemapEntries({
  siteUrl,
  posts,
}: {
  siteUrl: string;
  posts: readonly PostRecord[];
}): SitemapEntry[] {
  const today = new Date().toISOString().slice(0, 10);
  // `/blog` 404s until a Post is published; `/projects` is always a page.
  const routes = posts.length > 0 ? ["", "/projects", "/blog"] : ["", "/projects"];
  const core = routes.map((route) => ({
    url: `${siteUrl}${route}`,
    lastModified: today,
  }));

  const postEntries = posts.map((post) => ({
    url: `${siteUrl}/blog/${encodeURIComponent(post.slug)}`,
    lastModified: post.publishedAt,
  }));

  return [...core, ...postEntries];
}

export function ogImagePath(title: string): string {
  return `/og?title=${encodeURIComponent(title)}`;
}
import { filterByQuery } from "@/lib/search";

/**
 * What a Post *is*, and the things you can do with one without touching a
 * disk.
 *
 * `lib/blog.ts` reads Posts off the filesystem, so anything that imports it is
 * server-only. A search box is not: it needs the shape, the date formatter and
 * the matcher in the browser. Splitting the pure half out is what lets the row
 * and the filter be shared by both sides instead of duplicated on one.
 */

export type PostFrontmatter = {
  title: string;
  publishedAt: string;
  summary: string;
  tags?: string[];
  draft?: boolean;
  image?: string;
};

export type PostRecord = PostFrontmatter & {
  slug: string;
  content: string;
  readingTimeMinutes: number;
};

/**
 * A Post minus its body: everything a row draws and a search reads, and
 * nothing a list of fifty has to ship down the wire.
 */
export type PostSummary = Omit<PostRecord, "content">;

export function formatPostDate(date: string): string {
  const value = date.includes("T") ? date : `${date}T00:00:00`;
  return new Date(value).toLocaleDateString("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
  });
}

/**
 * Title, summary and tags. Not the body — a filter that matched body text
 * would return a Post whose row shows nothing of why it matched, which reads
 * as a bug even when it is a hit.
 */
export function searchPosts<
  T extends Pick<PostSummary, "title" | "summary" | "tags">,
>(posts: readonly T[], query: string): T[] {
  return filterByQuery(posts, query, (post) => [
    post.title,
    post.summary,
    ...(post.tags ?? []),
  ]);
}

export function findNeighbours<T extends { slug: string }>(
  posts: readonly T[],
  slug: string,
): { newer: T | null; older: T | null } {
  const index = posts.findIndex((post) => post.slug === slug);
  if (index === -1) return { newer: null, older: null };
  return {
    newer: posts[index - 1] ?? null,
    older: posts[index + 1] ?? null,
  };
}

/**
 * The post as plain markdown: what "Copy page" puts on the clipboard and what
 * `/blog/<slug>/raw.md` serves.
 *
 * The frontmatter is bookkeeping for the build, so it is not reproduced; the
 * two facts it holds that a reader wants — what this is and when it was
 * written — are restated as text instead. The canonical URL rides along
 * because the likeliest next thing to happen to this string is being pasted
 * into a model, and a model that cannot cite where the words came from will
 * invent somewhere.
 */
export function postMarkdown(
  post: Pick<PostSummary, "title" | "summary" | "publishedAt">,
  url: string,
  content: string,
): string {
  return (
    [
      `# ${post.title}`,
      `> ${post.summary}`,
      `${formatPostDate(post.publishedAt)} · ${url}`,
      content.trim(),
    ].join("\n\n") + "\n"
  );
}

